//go:build arm64

package floats

// Maximum and Minimum kernels (maxmin.go), generated by go-asmgen
// (maxmin_arm64_gen.go) into maxmin_arm64.s. NEON is the ARMv8-A baseline: no
// gate. A kernel does the whole blocks of eight elements of slices whose length is
// a positive multiple of eight; the Go code finishes the last seven with the
// scalar rule. No kernel keeps a pointer: every stub is go:noescape.
//
//go:noescape
func maximumNEON(dst, a, b []float64)

//go:noescape
func minimumNEON(dst, a, b []float64)

func vmaximum(dst, a, b []float64) {
	n := len(a) &^ 7
	if n > 0 {
		maximumNEON(dst[:n], a[:n], b[:n])
	}
	maximumRef(dst[n:], a[n:], b[n:])
}

func vminimum(dst, a, b []float64) {
	n := len(a) &^ 7
	if n > 0 {
		minimumNEON(dst[:n], a[:n], b[:n])
	}
	minimumRef(dst[n:], a[n:], b[n:])
}
